package cn.huankan.event;
import cn.huankan.evidence.EvidenceService;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
@Service public class PracticalIntelligenceService {
 public static final String RULE="金融证据规则简报-1.1";
 private final JdbcTemplate db;private final ObjectMapper json;private final MacroResearchService macro;
 public PracticalIntelligenceService(JdbcTemplate d,ObjectMapper j,MacroResearchService m){db=d;json=j;macro=m;}
 public record Query(String date,String source,String topic,boolean watchOnly,int page){}
 private static final Map<String,String> TOPICS=Map.of("全球货币政策","央行利率政策","全球通胀","通货膨胀","全球就业","就业","全球利率","央行利率政策","全球汇率","外汇","AI与科技产业","人工智能技术","半导体","半导体","商品和能源","能源","风险事件","金融监管","全球企业公告","企业财报");
 private String text(String x){return x==null?"":x;}private String topic(String x){if(text(x).isEmpty())return "";if(!TOPICS.containsKey(x))throw new IllegalArgumentException("研究专题无效");return TOPICS.get(x);}
 private void validate(Query q){if(q.page()<0||q.page()>10000)throw new IllegalArgumentException("页码无效");topic(q.topic());if(!text(q.source()).isEmpty()&&!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM source_registry WHERE id=?)",Boolean.class,q.source())))throw new IllegalArgumentException("来源不在真实目录");}
 private String encode(Object v){try{return json.writeValueAsString(v);}catch(Exception e){throw new IllegalArgumentException("简报编码失败",e);}}
 private Map<String,Object> decode(Map<String,Object> r,String... names){for(String n:names)if(r.get(n)!=null)try{r.put(n,json.readTree(r.get(n).toString()));}catch(Exception e){throw new IllegalArgumentException("研究数据格式异常");}return r;}
 public Object catalog(){return Map.of("topics",TOPICS.keySet().stream().sorted().toList(),"sources",db.queryForList("SELECT id,name,region,level FROM source_registry ORDER BY id"),"series",macro.catalog(),"rule_version",RULE);}
 public Object monitor(){return Map.of("checked_at",Instant.now(),"sources",db.queryForList("SELECT s.id,s.name,s.region,s.level,s.enabled,s.interval_seconds,l.status license_status,j.status last_task_status,j.http_status,j.started_at last_attempt,j.finished_at last_completion,j.error_code,(SELECT max(completed_at) FROM http_request_observation h WHERE h.source_id=s.id AND status IN(200,304)) last_successful_check,r.published_at latest_publication,r.first_seen_at,r.collected_at,r.source_url,e.original_title latest_title,CASE WHEN r.published_at IS NOT NULL THEN extract(epoch FROM r.first_seen_at-r.published_at) END discovery_delay_seconds,CASE WHEN j.status='RUNNING' AND j.started_at<now()-interval '10 minutes' THEN 'STALE_RUNNING' WHEN j.status='FAILED' THEN 'CHECK_FAILED' WHEN s.enabled AND j.finished_at<now()-make_interval(secs=>s.interval_seconds*2) THEN 'CHECK_OVERDUE' ELSE 'RECORDED' END monitor_state FROM source_registry s JOIN source_license l ON l.source_id=s.id LEFT JOIN LATERAL(SELECT * FROM ingestion_job WHERE source_id=s.id ORDER BY started_at DESC LIMIT 1)j ON true LEFT JOIN LATERAL(SELECT * FROM raw_evidence WHERE source_id=s.id ORDER BY published_at DESC NULLS LAST,collected_at DESC LIMIT 1)r ON true LEFT JOIN financial_event e ON e.evidence_id=r.id ORDER BY s.id"),"calendar",db.queryForList("SELECT c.*,s.name publisher FROM official_release_calendar c JOIN source_registry s ON s.id=c.source_id WHERE planned_date>=current_date-7 AND planned_date<=current_date+90 ORDER BY planned_date,id LIMIT 100"),"state","计划日期不是实际发布时间；没有官方时间时不计算公告延迟。异常窗口表示需要核查，不断言一定遗漏。");}
 public List<Map<String,Object>> cards(Query q,String owner){validate(q);return cardsAt(q,owner,null,null,50,true);}
 private List<Map<String,Object>> cardsAt(Query q,String owner,Instant start,Instant end,int limit,boolean official){
  String sql="SELECT e.id,e.original_title,e.chinese_title,e.translation_status,e.category,e.source_id,s.name publisher,s.level,r.id evidence_id,r.source_url,r.raw_content_hash,r.published_at,r.first_seen_at,r.collected_at,r.ingestion_kind,(SELECT count(*) FROM raw_evidence old WHERE old.source_id=r.source_id AND old.source_document_id=r.source_document_id) evidence_versions,COALESCE(g.priority,0) research_priority,g.topics,m.series_id,m.observation_date,m.value,m.version local_version,(SELECT jsonb_agg(jsonb_build_object('fact_id',f.id,'fields',f.fields,'status',COALESCE((SELECT decision FROM fact_review v WHERE v.fact_id=f.id ORDER BY created_at DESC,id DESC LIMIT 1),f.verification_status))) FROM fact_candidate f WHERE f.observation_id=r.id OR f.event_id=e.id) facts FROM financial_event e JOIN raw_evidence r ON r.id=e.evidence_id JOIN source_registry s ON s.id=e.source_id JOIN source_license l ON l.source_id=s.id LEFT JOIN governed_message g ON g.event_id=e.id LEFT JOIN macro_observation m ON m.evidence_id=r.id WHERE l.status='APPROVED' AND l.display_allowed AND (l.valid_until IS NULL OR l.valid_until>now()) AND s.level"+(official?"='L0'":"='L2'")+" AND (?='' OR e.source_id=?) AND (?='' OR g.topics ?? ? OR (?='全球汇率' AND m.series_id LIKE 'EXR.%') OR (?='全球利率' AND m.series_id LIKE 'FM.%')) AND (NOT ? OR watch_matches(?,r.id,e.id,s.id,s.level,COALESCE(g.priority,0)))";
  var args=new ArrayList<Object>(List.of(text(q.source()),text(q.source()),topic(q.topic()),topic(q.topic()),text(q.topic()),text(q.topic()),q.watchOnly(),owner));
  if(start!=null){sql+=official?" AND r.published_at>=? AND r.published_at<?":" AND r.first_seen_at>=? AND r.first_seen_at<?";args.add(java.sql.Timestamp.from(start));args.add(java.sql.Timestamp.from(end));}
  sql+=" ORDER BY COALESCE(r.published_at,r.collected_at) DESC,e.id LIMIT ? OFFSET ?";args.add(limit);args.add(q.page()*limit);
  var rows=db.queryForList(sql,args.toArray());for(var r:rows){decode(r,"topics","facts");r.put("key_numbers",r.get("value"));r.put("actual_observation_period",r.get("observation_date"));r.put("importance_boundary","规则研究优先级，不等同实际市场反应；没有实质事实时保持待核查");if(r.get("series_id")!=null){var comp=new PriorityService(db,json).change(r);r.put("macro_change",comp);if(comp.get("previous") instanceof Map prev){var c=new LinkedHashMap<String,Object>(prev);c.put("difference",comp.get("difference"));c.put("interpretation",comp.get("comparison_status"));r.put("historical_comparison",c);}}
r.put("fact_boundary","来源确认与字段一致性分别看事实状态；不是多来源独立共证");r.put("mechanism",r.get("series_id")==null?"需结合公告实质与真实敞口；标题本身不足以证明金融影响":"同口径观测变化可能通过融资成本或外币收支传导，方向须结合真实敞口");r.put("possible_markets",List.of("条件性关联：利率、外汇及权益市场；未取得合法行情验证"));r.put("counter_explanation","相邻观测或同时发生不证明因果，已有预期和其他因素可能解释变化");r.put("missing_evidence",List.of("市场一致预期与合法行情缺失","企业敞口和真实业务关系不足","部分公告仅核对原始标题，实质事实仍待核实"));r.put("watch_variables",List.of("后续官方披露","同口径观测或修订","原始证据变化"));r.put("market_status","尚未获得行情验证");r.put("ai_hypotheses",List.of());}return rows;
 }
 public Object detail(UUID id){var e=db.queryForMap("SELECT e.*,s.name publisher FROM financial_event e JOIN source_registry s ON s.id=e.source_id JOIN source_license l ON l.source_id=s.id WHERE e.id=? AND l.status='APPROVED' AND l.display_allowed AND (l.valid_until IS NULL OR l.valid_until>now())",id);var evidence=db.queryForList("SELECT r.id,r.source_id,r.source_url,r.raw_content_hash,r.published_at,r.first_seen_at,r.collected_at,r.revision,r.ingestion_kind,encode(sha256(r.raw_content),'hex')=r.raw_content_hash hash_passed FROM event_evidence p JOIN raw_evidence r ON r.id=p.evidence_id WHERE p.event_id=? ORDER BY r.revision,r.collected_at LIMIT 100",id);return Map.of("event",e,"evidence",evidence,"timeline",evidence,"classification","相同官方来源和document_id保留一份主事件；全部证据版本按时间保留。不凭名称相似合并不同事件。","market_status","尚未获得行情验证");}
 public Object macro(String series,int page){if(page<0||page>10000||series==null||series.length()>100)throw new IllegalArgumentException("指标查询无效");var definition=db.queryForMap("SELECT m.*,s.name publisher FROM macro_series m JOIN source_registry s ON s.id=m.source_id JOIN source_license l ON l.source_id=s.id WHERE m.id=? AND l.status='APPROVED' AND l.display_allowed AND (l.valid_until IS NULL OR l.valid_until>now())",series);decode(definition,"metadata");var rows=db.queryForList("SELECT m.*,r.source_url,r.raw_content_hash,r.published_at,r.collected_at FROM macro_observation m JOIN raw_evidence r ON r.id=m.evidence_id WHERE m.series_id=? ORDER BY m.observation_date DESC,m.version DESC LIMIT 120 OFFSET ?",series,page*120);return Map.of("definition",definition,"observations",rows,"history",db.queryForList("SELECT observation_date,value,version,collected_at,source_published_at,source_vintage_at FROM macro_history_version WHERE series_id=? ORDER BY observation_date DESC,version DESC LIMIT 120 OFFSET ?",series,page*120),"version_boundary","系统本地观测版本不等于官方源端vintage；首次可获得时间以真实采集记录为准，不能准确复原所有历史交易时点");}
 @Transactional(isolation=Isolation.REPEATABLE_READ) public Object generate(Query q,String owner){validate(q);LocalDate day=LocalDate.parse(q.date());Instant queried=Instant.now(),start=day.atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant(),end=day.plusDays(1).atStartOfDay(ZoneId.of("Asia/Shanghai")).toInstant();if(start.isAfter(queried))throw new IllegalArgumentException("不能生成未来简报");if(end.isAfter(queried))end=queried;var scope=new Query(q.date(),q.source(),q.topic(),q.watchOnly(),0);var official=cardsAt(scope,owner,start,end,2000,true);for(var r:official){var cats=PriorityRules.categories(r.get("original_title").toString(),(String)r.get("series_id"));String status="EXTRACTED";if(r.get("facts") instanceof JsonNode facts&&!facts.isEmpty())status=facts.get(0).path("status").asText("EXTRACTED");var sc=PriorityRules.score(new PriorityRules.Input(r.get("id").toString(),r.get("evidence_id").toString(),r.get("level").toString(),r.get("publisher").toString(),r.get("published_at") instanceof java.sql.Timestamp t?t.toInstant():null,queried,true,status,cats,q.watchOnly(),false,false,((Number)r.get("evidence_versions")).intValue()>1));r.put("research_priority",sc.total());r.put("priority_reasons",sc.reasons());r.put("priority_rule",PriorityRules.VERSION);}official.sort(Comparator.<Map<String,Object>>comparingInt(r->(int)r.get("research_priority")).reversed().thenComparing(r->r.get("id").toString()));boolean officialTruncated=official.size()>20;official=new ArrayList<>(official.subList(0,Math.min(20,official.size())));var leads=cardsAt(scope,owner,start,end,20,false);
  var observations=db.queryForList("SELECT m.*,r.source_url,r.raw_content_hash,r.collected_at,r.published_at,s.name publisher FROM macro_observation m JOIN raw_evidence r ON r.id=m.evidence_id JOIN financial_event e ON e.evidence_id=r.id JOIN source_registry s ON s.id=r.source_id JOIN source_license l ON l.source_id=s.id WHERE r.collected_at>=? AND r.collected_at<? AND l.status='APPROVED' AND l.display_allowed AND (l.valid_until IS NULL OR l.valid_until>now()) AND (?='' OR r.source_id=?) AND (?='' OR m.series_id LIKE ? OR m.series_id LIKE ?) AND (NOT ? OR watch_matches(?,r.id,e.id,s.id,s.level,0)) ORDER BY r.collected_at DESC,m.observation_date DESC LIMIT 30",java.sql.Timestamp.from(start),java.sql.Timestamp.from(end),text(q.source()),text(q.source()),text(q.topic()),seriesPatterns(q.topic())[0],seriesPatterns(q.topic())[1],q.watchOnly(),owner);
  // Topics also constrain numeric inputs; an unavailable industry must not acquire unrelated macro values.
  if(!text(q.topic()).isEmpty())observations.removeIf(r->!matchesSeries(q.topic(),r.get("series_id").toString()));
  var reports=q.watchOnly()?new ArrayList<Map<String,Object>>():db.queryForList("SELECT id,series_id,as_of,rule_version,report,inputs FROM research_input_snapshot WHERE created_at>=? AND created_at<? AND as_of<=? AND (?='' OR series_id IN(SELECT id FROM macro_series WHERE source_id=?)) AND (?='' OR series_id LIKE ? OR series_id LIKE ?) ORDER BY created_at DESC LIMIT 10",java.sql.Timestamp.from(start),java.sql.Timestamp.from(end),java.sql.Timestamp.from(queried),text(q.source()),text(q.source()),text(q.topic()),seriesPatterns(q.topic())[0],seriesPatterns(q.topic())[1]);
  reports.removeIf(r->(!text(q.source()).isEmpty()&&!Objects.equals(db.queryForObject("SELECT source_id FROM macro_series WHERE id=?",String.class,r.get("series_id")),q.source()))||(!text(q.topic()).isEmpty()&&!matchesSeries(q.topic(),r.get("series_id").toString())));
  for(var r:reports)decode(r,"report","inputs");
  var anomalies=db.queryForList("SELECT s.id,s.name,s.enabled,j.status,j.http_status,j.error_code,j.started_at,j.finished_at FROM source_registry s LEFT JOIN LATERAL(SELECT * FROM ingestion_job WHERE source_id=s.id ORDER BY started_at DESC LIMIT 1)j ON true WHERE (?='' OR s.id=?) AND (j.status='FAILED' OR NOT s.enabled OR j.status='RUNNING' AND j.started_at<now()-interval '10 minutes') ORDER BY s.id",text(q.source()),text(q.source()));
  var evidence=new LinkedHashMap<String,Map<String,Object>>();for(var rows:List.of(official,leads,observations))for(var r:rows){Object id=r.get("evidence_id");if(id==null)continue;var proof=db.queryForMap("SELECT id,source_id,source_url,raw_content_hash,encode(sha256(raw_content),'hex') actual_hash,published_at,collected_at FROM raw_evidence WHERE id=?",id);if(!proof.get("raw_content_hash").equals(proof.get("actual_hash")))throw new IllegalStateException("简报证据哈希失败");evidence.put(id.toString(),proof);}
  for(var frozen:reports){for(var input:(JsonNode)frozen.get("inputs")){if(!input.hasNonNull("evidence_id"))throw new IllegalStateException("研究快照缺少证据ID");String key=input.get("evidence_id").asText();var proof=db.queryForMap("SELECT id,source_id,source_url,raw_content_hash,encode(sha256(raw_content),'hex') actual_hash,published_at,collected_at FROM raw_evidence WHERE id=?",UUID.fromString(key));if(!proof.get("raw_content_hash").equals(proof.get("actual_hash")))throw new IllegalStateException("研究输入哈希失败");evidence.put(key,proof);}}UUID id=UUID.randomUUID(),snapshot=UUID.randomUUID();var report=new LinkedHashMap<String,Object>();report.put("coverage",Map.of("start",start,"end",end,"timezone","Asia/Shanghai","queried_at",queried,"limits",Map.of("official_events",20,"unverified_leads",20,"macro_observations",30,"research_snapshots",10),"scope_note","按指定过滤条件选取有界近期证据，非全量新闻总结"));report.put("official_events",official);report.put("priority_boundary",officialTruncated?"符合范围官方候选超过20条，按可解释规则选前20条；不是全日事件总数":"当前范围内官方候选按可解释规则排序");report.put("research_events",official.stream().filter(r->((Number)r.get("research_priority")).intValue()>=50).toList());report.put("impact_hypotheses",reports);report.put("counter_evidence",List.of("市场预期、行情与公司真实敞口不足；相邻统计变化不能证明因果"));report.put("macro_observations",observations);report.put("industry_events",official.stream().filter(r->PriorityRules.categories(r.get("original_title").toString(),(String)r.get("series_id")).stream().anyMatch(Set.of("重大企业披露","AI与半导体","光通信与数据中心","能源与大宗商品","产业链重大变化")::contains)).toList());report.put("risks",List.of("当前显示的是证据支持的观测与条件研究，缺乏行情及真实市场一致预期；风险方向尚未证实"));report.put("supported_hypotheses",reports);report.put("unverified_leads",leads);report.put("watch_variables",List.of("后续官方发布","同口径数值和脚注修订","源端许可与连接恢复"));report.put("source_gaps",anomalies);report.put("evidence_catalog",new ArrayList<>(evidence.values()));report.put("generation","结构化规则简报；没有AI模型执行，没有虚构行情或市场预期");report.put("unknown_publication","宏观条目按实际采集范围收录，不声称当日新发布；发布未知保留未知");String inputs=encode(Map.of("official_events",official,"macro_observations",observations,"evidence",evidence.values(),"research_snapshots",reports,"source_filter",text(q.source()),"topic_filter",text(q.topic()),"watch_only",q.watchOnly(),"watch_rules",q.watchOnly()?db.queryForList("SELECT kind,value,label,include_leads,minimum_priority FROM user_watch WHERE owner_key=? AND enabled ORDER BY kind,value",owner):List.of()));String status=official.isEmpty()&&leads.isEmpty()&&observations.isEmpty()&&reports.isEmpty()?"NO_MATCHING_DATA":"RULE_GENERATED";
  db.update("INSERT INTO financial_brief(id,owner_key,coverage_start,coverage_end,queried_at,source_filter,topic_filter,watch_only,rule_version,snapshot_id,input_hash,report,inputs,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?::jsonb,?::jsonb,?)",id,owner,java.sql.Timestamp.from(start),java.sql.Timestamp.from(end),java.sql.Timestamp.from(queried),text(q.source()),text(q.topic()),q.watchOnly(),RULE,snapshot,db.queryForObject("SELECT encode(sha256(convert_to(?::jsonb::text,'UTF8')),'hex')",String.class,inputs),encode(report),inputs,status);return brief(id,owner);
 }
 private String[] seriesPatterns(String topic){return switch(text(topic)){case "全球汇率"->new String[]{"EXR.%","EXR.%"};case "全球利率","全球货币政策"->new String[]{"FM.%","FM.%"};case "全球通胀"->new String[]{"CU%","WP%"};case "全球就业"->new String[]{"LN%","CE%"};default->new String[]{"__UNAVAILABLE_SERIES__%","__UNAVAILABLE_SERIES__%"};};}
 private boolean matchesSeries(String topic,String s){return switch(topic){case "全球汇率"->s.startsWith("EXR.");case "全球利率","全球货币政策"->s.startsWith("FM.");case "全球通胀"->s.startsWith("CU")||s.startsWith("WP");case "全球就业"->s.startsWith("LN")||s.startsWith("CE");default->false;};}
 public Object briefs(Query q,String owner){validate(q);return db.queryForList("SELECT id,coverage_start,coverage_end,queried_at,rule_version,snapshot_id,input_hash,status,source_filter,topic_filter,watch_only FROM financial_brief WHERE owner_key=? AND (?='' OR coverage_start>=?::date::timestamp AT TIME ZONE 'Asia/Shanghai' AND coverage_start<(?::date+1)::timestamp AT TIME ZONE 'Asia/Shanghai') AND (?='' OR source_filter=?) AND (?='' OR topic_filter=?) ORDER BY queried_at DESC LIMIT 50 OFFSET ?",owner,text(q.date()),text(q.date()).isEmpty()?"1900-01-01":q.date(),text(q.date()).isEmpty()?"1900-01-01":q.date(),text(q.source()),text(q.source()),text(q.topic()),text(q.topic()),q.page()*50);}
 public Object brief(UUID id,String owner){return decode(db.queryForMap("SELECT * FROM financial_brief WHERE id=? AND owner_key=?",id,owner),"report","inputs");}
}
